clipboardHistory.value:
hl.bind("ALT + mouse:274",
    hl.dsp.exec_cmd([[hyprctl eval 'hl.config({ cursor = { zoom_factor = 1.0 } })']])
)

hl.bind(" ALT + mouse_down",
    hl.dsp.exec_cmd([[sh -c 'hyprctl eval "hl.config({ cursor = { zoom_factor = $(hyprctl getoption cursor:zoom_factor | awk '\''/^float/ { v=$2-0.25; if (v<1.0) v=1.0; print v }'\'') } })"' ]])
)

hl.bind(mainMod .. " + mouse_down",
    hl.dsp.exec_cmd([[sh -c 'hyprctl eval "hl.config({ cursor = { zoom_factor = $(hyprctl getoption cursor:zoom_factor | awk '\''/^float/ {print $2 + 0.25}'\'') } })"' ]])
)

hl.bind(mainMod .. " + mouse_up",
    hl.dsp.exec_cmd([[sh -c 'hyprctl eval "hl.config({ cursor = { zoom_factor = $(hyprctl getoption cursor:zoom_factor | awk '\''/^float/ { v=$2-0.25; if (v<1.0) v=1.0; print v }'\'') } })"' ]])
)
